const RATE = { watch: 0.03, act: 0.06, urgent: 0.10 };

function bucket(days) {
  if (days >= 90) return 'urgent';
  if (days >= 60) return 'act';
  return 'watch';
}

// Round to the nearest 500 AED. Nobody lists a car at 47,312.
const round500 = (n) => Math.max(500, Math.round(n / 500) * 500);

const out = [];

for (const item of $input.all()) {
  const v = item.json;

  const days = Number(v.days_on_lot);
  const current = Number(v.list_price_aed);
  const cost = Number(v.acquisition_cost_aed);
  const holding = Number(v.holding_cost_aed);
  const margin = Number(v.margin_at_list_aed);

  const severity = bucket(days);
  let cut = RATE[severity];

  // Already under water: cutting further only deepens the loss, so recommend the
  // smallest move that might actually shift it rather than a percentage of a price
  // that is no longer the problem.
  const underwater = margin < 0;
  if (underwater) cut = Math.min(cut, 0.04);

  const recommended = round500(current * (1 - cut));

  // The recall check is a second source and is allowed to fail — see the workflow's
  // error handling. Absent data must never read as "no recalls".
  //
  // The Merge node hands over task 01's raw API response, so the recall list arrives as
  // `recalls`, an array. An earlier version of this code expected a pre-summarised
  // `recall` object, which silently made every car read as "unknown" and meant the
  // do-not-retail branch never fired. Both shapes are accepted now, and anything else
  // is treated as unknown rather than clear.
  let recallKnown = false;
  let parkIt = 0;
  let openCampaigns = null;

  if (Array.isArray(v.recalls)) {
    recallKnown = true;
    openCampaigns = v.recalls.length;
    parkIt = v.recalls.filter((r) => r && (r.parkIt === true || r.parkIt === 'true')).length;
  } else if (v.recall && v.recall.ok === true) {
    recallKnown = true;
    openCampaigns = v.recall.campaigns ?? null;
    parkIt = v.recall.parkIt ?? 0;
  }

  const reasons = [];
  reasons.push(`${days} days on the lot, ${holding.toLocaleString()} AED of carrying cost so far`);
  if (underwater) reasons.push(`asking price no longer covers cost plus carry (margin ${margin.toLocaleString()} AED)`);
  else reasons.push(`margin at list ${margin.toLocaleString()} AED`);

  if (parkIt > 0) reasons.push(`${parkIt} "do not drive" recall${parkIt === 1 ? '' : 's'} open — do not retail until repaired`);
  else if (openCampaigns) reasons.push(`${openCampaigns} open recall campaign${openCampaigns === 1 ? '' : 's'}`);
  else if (!recallKnown) reasons.push('recall status unavailable, not confirmed clear');

  out.push({
    json: {
      vehicle_id: v.id,
      owner_id: v.owner_id,
      vin: v.vin,
      label: `${v.year ?? ''} ${v.make} ${v.model}`.trim(),
      days_on_lot: days,
      holding_cost_aed: Math.round(holding),
      current_price_aed: current,
      recommended_price_aed: recommended,
      cut_aed: current - recommended,
      severity,
      // parkIt outranks ageing: a car that should not be driven is not a pricing problem
      priority: parkIt > 0 ? 'blocked' : severity,
      rationale: reasons.join('. ') + '.',
      recall_known: Boolean(recallKnown),
      park_it: parkIt,
      open_campaigns: openCampaigns,
      cost_aed: cost,
    },
  });
}

return out;

// Builds the nightly digest and counts what the idempotency guard did.
//
// PostgREST with on_conflict + Prefer: resolution=ignore-duplicates returns the rows it
// inserted and omits the ones that collided with the unique constraint - so "written"
// versus "already recorded" falls straight out of the response.
//
// Formatting is Discord-native: headings, a monospace block per severity band so the
// figures line up, and small subtext for the caveats. A pricing review is skimmed on a
// phone, so the shape has to carry the meaning before the words do.
//
// Deliberately ASCII only. The first version used arrows, typographic minus signs and
// emoji; they came back through the webhook mangled (-> became a mojibake run), and a
// pricing digest does not need them. Consecutive '-#' subtext lines also collapse into
// one paragraph in Discord, so the caveats are joined into a single line on purpose.

const everything = $('Score the markdown').all().map((i) => i.json);

// Cars held back by a "do not drive" recall never reach the markdown table - they are
// alerted on their own path - so they must not be counted as "skipped" here.
const blocked = everything.filter((s) => s.priority === 'blocked');
const scored = everything.filter((s) => s.priority !== 'blocked');

const written = $input
  .all()
  .flatMap((i) => (Array.isArray(i.json) ? i.json : [i.json]))
  .filter((r) => r && r.id);

const writtenIds = new Set(written.map((r) => r.vehicle_id));
const skipped = scored.filter((s) => !writtenIds.has(s.vehicle_id));

const n = (v) => Number(v).toLocaleString('en-AE');
const date = new Date().toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric' });

// Fixed-width rows inside a code block: the columns align, which is what makes a list
// of numbers skimmable rather than a wall of text.
const row = (s) => {
  // The model year is dropped here: it is on the dashboard, and keeping it truncated
  // "Porsche 718 Caym" mid-word, which looks broken. Without it the longest name on the
  // lot (Land Rover Range Rover) fits exactly.
  const name = s.label.replace(/^\d{4}\s+/, '');
  return (
    `${name.slice(0, 22).padEnd(22)} ${String(s.days_on_lot).padStart(3)}d  ` +
    `${n(s.current_price_aed).padStart(7)} -> ${n(s.recommended_price_aed).padStart(7)}  ` +
    `${('-' + n(s.cut_aed)).padStart(7)}`
  );
};

const band = (title, items) =>
  items.length ? [`### ${title} (${items.length})`, '```', ...items.map(row), '```'] : [];

const urgent = scored.filter((s) => s.severity === 'urgent');
const act = scored.filter((s) => s.severity === 'act');
const watch = scored.filter((s) => s.severity === 'watch');
const totalCut = scored.reduce((sum, s) => sum + s.cut_aed, 0);

const parts = [`## Nightly markdown review`, `**${date}**`, ''];

parts.push(
  `**${scored.length + blocked.length}** vehicles past 30 days  |  ` +
  `**${written.length}** new recommendation${written.length === 1 ? '' : 's'}  |  ` +
  `**${skipped.length}** already recorded today`,
);

if (blocked.length) {
  parts.push(
    `> **${blocked.length}** vehicle${blocked.length === 1 ? '' : 's'} held back for open ` +
    `"do not drive" recalls - posted separately.`,
  );
}

parts.push('');
parts.push(...band('Over 90 days - act now', urgent));
parts.push(...band('60 to 89 days', act));
parts.push(...band('Watch list - 30 to 59 days', watch));

parts.push(`**Total proposed reduction: AED ${n(totalCut)}**`);
// One subtext line, not two: consecutive '-#' lines run together into a single
// paragraph in Discord, which reads as a typo.
const unknown = scored.filter((s) => !s.recall_known).length;
const caveats = ['Nothing has been applied - these are recommendations for a human to approve.'];
if (unknown) {
  caveats.push(`Recall status unavailable for ${unknown} vehicle${unknown === 1 ? '' : 's'}, treated as unknown rather than clear.`);
}
parts.push(`-# ${caveats.join('  |  ')}`);

let content = parts.join('\n');

// Discord rejects anything over 2000 characters with a 400, which would lose the whole
// digest rather than the tail of it. Trim to the last complete line that fits, and close
// any code block the trim may have cut open.
const LIMIT = 1900;
if (content.length > LIMIT) {
  let kept = content.slice(0, LIMIT).split('\n').slice(0, -1).join('\n');
  if ((kept.match(/```/g) || []).length % 2 === 1) kept += '\n```';
  content = `${kept}\n-# Truncated. ${scored.length} vehicles in full - see the dashboard.`;
}

return [{ json: { content, written: written.length, skipped: skipped.length } }];

// The handled failure branch. One bad response must not end the run silently — the
// point of error handling is that somebody finds out, and that they are told enough to
// act without opening n8n.

const item = $input.first().json ?? {};

// n8n shapes the error output differently depending on where it came from, so try the
// forms it actually uses rather than assuming one.
const raw = item.error ?? item;
const message =
  (typeof raw === 'string' && raw) ||
  raw?.message ||
  raw?.description ||
  item.message ||
  'unknown error';

// $prevNode is the node that routed into this one, which is the stage that failed.
const stage = $prevNode?.name || 'unknown stage';

const hint =
  /credential/i.test(message)
    ? 'Attach the Supabase credential to the Supabase nodes, then run again.'
    : /fetch|ENOTFOUND|ETIMEDOUT|socket/i.test(message)
      ? 'Upstream did not respond. It was retried with backoff before this alert.'
      : 'Open the execution in n8n for the full trace.';

const text = [
  '**Nightly markdown review FAILED**',
  `Stage: ${stage}`,
  `Error: ${message}`,
  `Next: ${hint}`,
  '',
  'No recommendations were recorded for this run. Re-running today is safe — the unique',
  'constraint on (vehicle, run date) means a partial run cannot create duplicates.',
].join('\n');

return [{ json: { content: text } }];

// The "do not retail" path. These cars are not a pricing problem, so they never reach
// the markdown table - they get their own message, immediately, and it leads with the
// instruction rather than with the data.

const cars = $input.all().map((i) => i.json);
if (cars.length === 0) return [];

const n = (v) => Number(v).toLocaleString('en-AE');

// ASCII only, and one subtext line rather than two - see digest.js for why.
const parts = [
  '## Do not retail',
  `**${cars.length}** vehicle${cars.length === 1 ? '' : 's'} on the lot ` +
  `${cars.length === 1 ? 'has' : 'have'} an open **"do not drive"** recall. ` +
  `Close the recall before ${cars.length === 1 ? 'it goes' : 'they go'} on sale - no markdown recommended.`,
  '',
];

for (const c of cars) {
  parts.push(`### ${c.label}`);
  parts.push('```');
  parts.push(`VIN            ${c.vin}`);
  parts.push(`Recalls        ${c.park_it} "do not drive"${c.open_campaigns ? ` of ${c.open_campaigns} open campaigns` : ''}`);
  parts.push(`Days on lot    ${c.days_on_lot}`);
  parts.push(`Asking         AED ${n(c.current_price_aed)}`);
  parts.push('```');
}

parts.push(
  '-# Recall data from NHTSA, matched by make, model and year rather than by VIN.  |  ' +
  'Confirm with the manufacturer whether this specific car has already been repaired.',
);

return [{ json: { content: parts.join('\n') } }];
